    labs=[
        dict(kind="linux", script="find-config", dir="mess", title="Find the real config file",
             goal=["Practise `find`, `grep` and counting, and prove you can answer three precise questions about a messy tree."],
             story=["A project folder has several lookalike files: `app.conf`, `app.conf.bak`, `old_app.conf` and more, buried in subfolders. Only one is the live config, and logs of different sizes are scattered around."],
             tasks=["Find the path of the file named **exactly** `app.conf` (not the `.bak` or `old_` ones).",
                    "Count how many `.log` files are larger than 1 KiB.",
                    "Read the port number set in the live config.",
                    "Write your three answers, one per line, as `conf=...` (path relative to the `mess` folder), `bigfiles=...` and `port=...`, into `~/sys-lab/answers.txt`."],
             check="Run the check script. It prints PASS or FAIL for each answer.", check_cmd="bash ~/sys-lab/check-find-config.sh",
             hints=["`find . -name app.conf` matches the name exactly. A pattern like `app.conf*` would also match the backups.",
                    "`find . -name \"*.log\" -size +1k` lists large logs. Pipe it into `wc -l` to count.",
                    "`grep` prints the line you need. `grep '^port' file` finds lines that start with port."],
             solution=["`cd ~/sys-lab/mess`, then `find . -name app.conf` gives `./projects/blog/deploy/app.conf`.",
                       "`find . -name '*.log' -size +1k | wc -l` gives 3.",
                       "`grep '^port' projects/blog/deploy/app.conf` gives `port=8080`.",
                       "Write the answers: `printf 'conf=projects/blog/deploy/app.conf\\nbigfiles=3\\nport=8080\\n' > ~/sys-lab/answers.txt`."]),
        dict(kind="linux", script="fix-permissions", dir="perm", title="Fix the permissions",
             goal=["Read permission problems and fix each with the smallest correct change, without `chmod 777`."],
             story=["A deploy folder was copied from a laptop and everything arrived with the wrong modes: the script will not run, the private key is readable by everyone, the team folder is closed to the team, and the website file is unreadable."],
             tasks=["Make `deploy.sh` runnable by its owner and readable and runnable by others (755).",
                    "Make `secret.key` private to the owner (600).",
                    "Give `shared/` full access to owner and group and none to others (770).",
                    "Make `public/index.html` readable by everyone but writable only by the owner (644)."],
             check="Run the check script. It prints the mode it found for each item.", check_cmd="bash ~/sys-lab/check-fix-permissions.sh",
             hints=["Use `ls -l` and `ls -ld shared` to see the current modes.", "`chmod 755 deploy.sh` sets a mode with numbers.", "Remember r=4, w=2, x=1. 770 is rwx for owner and group, nothing for others."],
             solution=["`cd ~/sys-lab/perm`", "`chmod 755 deploy.sh`", "`chmod 600 secret.key`", "`chmod 770 shared`", "`chmod 644 public/index.html`"]),
        dict(kind="linux", script="top-ips", dir="weblogs", title="Top clients with one pipeline",
             goal=["Build a pipeline from scratch to answer a real operations question."],
             story=["Traffic spiked and you suspect one client is hammering the site. The log has one request per line, starting with the client's IP address."],
             tasks=["Using only a pipeline (no editor), list the **three clients with the most requests**, most first.",
                    "Save the result in `~/sys-lab/top3.txt`. Each line should be the count followed by the IP (what `uniq -c` prints)."],
             check="Run the check script.", check_cmd="bash ~/sys-lab/check-top-ips.sh",
             hints=["The IP is the first space-separated field: `cut -d' ' -f1`.", "`uniq` only collapses neighbouring duplicates, so `sort` first.", "`sort -rn` sorts numbers biggest first, and `head -3` keeps three lines."],
             solution=["`cut -d' ' -f1 ~/sys-lab/weblogs/web.log | sort | uniq -c | sort -rn | head -3 > ~/sys-lab/top3.txt`"]),
    ],
    cases=[
        dict(title="The command that ran on the wrong server",
             story=["In January 2017 an engineer at GitLab was fixing a broken database replica. Tired and late at night, they ran a command to wipe a data directory, believing they were on the replica. They were on the primary. They noticed within a second or two, but about 300 GB of production data was already gone.",
                    "Recovery was made worse by something unrelated to the typo: several of the backup mechanisms were not working, and the failures had gone unnoticed. GitLab published a detailed, blameless postmortem and even streamed the recovery publicly."],
             lesson="Destructive commands deserve a pause to confirm **which machine and which directory** you are on (check the prompt, `hostname` and `pwd`). The postmortem's larger lesson: backups you have never restored are a hope, not a safety net.",
             url="https://about.gitlab.com/blog/2017/02/10/postmortem-of-database-outage-of-january-31/"),
        dict(title="An empty variable in an rm -rf",
             story=["In January 2015 a user reported that launching Steam on Linux deleted a large amount of their files after they had moved Steam's folder. Commenters on the public issue pointed at a line in Steam's start-up script of the form `rm -rf \"$STEAMROOT/\"*`, and discussed how an empty variable would turn that into a deletion starting at the filesystem root.",
                    "Be careful with the facts: the user's account and the commenters' theory are what the issue records; Valve's own explanation is not on that page. The pattern, however, is real and well known."],
             lesson="In scripts, never run a recursive delete on a path built from a variable that might be empty. Use `set -u` (error on unset variables), check the value first, and quote the variable. This is why careful engineers write `rm -rf -- \"${DIR:?}/\"*`.",
             url="https://github.com/ValveSoftware/steam-for-linux/issues/3671"),
    ],
